mapper.select:
SELECT post_id, count(*) AS count FROM likes WHERE post_id IN
#{postId}
GROUP BY post_id

SELECT l.id AS like_id, u.id AS user_id, u.username, u.display_name, u.avatar_key, u.bio
FROM likes l JOIN users u ON u.id = l.user_id
WHERE l.post_id = #{postId}
AND l.id < #{cursor}
ORDER BY l.id DESC
LIMIT #{limit}
